-- BefineSaaS - MySQL seed data
-- Generated 2026-07-07. Charset utf8mb4. Safe to rerun with ON DUPLICATE KEY UPDATE.

CREATE DATABASE IF NOT EXISTS befine_saas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE befine_saas;

CREATE TABLE IF NOT EXISTS stores (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  owner VARCHAR(255),
  phone VARCHAR(32),
  email VARCHAR(255),
  address VARCHAR(500),
  plan VARCHAR(100),
  tax_code VARCHAR(64),
  currency VARCHAR(16) DEFAULT 'VND',
  website VARCHAR(255),
  status VARCHAR(32) DEFAULT 'active',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS warehouses (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  address VARCHAR(500),
  manager VARCHAR(255),
  status VARCHAR(32) DEFAULT 'active'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS channels (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  type VARCHAR(64),
  status VARCHAR(64),
  revenue BIGINT DEFAULT 0,
  orders_count INT DEFAULT 0,
  sync_status VARCHAR(255),
  icon VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS products (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  sku VARCHAR(100) UNIQUE,
  barcode VARCHAR(100),
  name VARCHAR(255) NOT NULL,
  category VARCHAR(120),
  brand VARCHAR(120),
  price BIGINT DEFAULT 0,
  cost BIGINT DEFAULT 0,
  stock INT DEFAULT 0,
  min_stock INT DEFAULT 0,
  warehouse VARCHAR(255),
  status VARCHAR(64),
  channels JSON,
  description TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS customers (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  phone VARCHAR(32),
  email VARCHAR(255),
  address VARCHAR(500),
  total_orders INT DEFAULT 0,
  total_spent BIGINT DEFAULT 0,
  debt BIGINT DEFAULT 0,
  tier VARCHAR(64),
  tags JSON,
  last_order DATE,
  join_date DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS staff (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  role VARCHAR(120),
  phone VARCHAR(32),
  email VARCHAR(255),
  status VARCHAR(64),
  branch VARCHAR(120),
  join_date DATE,
  salary BIGINT DEFAULT 0,
  orders_count INT DEFAULT 0,
  permission VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS suppliers (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  contact VARCHAR(255),
  phone VARCHAR(32),
  email VARCHAR(255),
  address VARCHAR(500),
  category VARCHAR(120),
  debt BIGINT DEFAULT 0,
  status VARCHAR(64),
  rating DECIMAL(3,1),
  last_import DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS orders (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  order_date DATETIME,
  customer_name VARCHAR(255),
  phone VARCHAR(32),
  total BIGINT DEFAULT 0,
  discount BIGINT DEFAULT 0,
  paid BIGINT DEFAULT 0,
  status VARCHAR(64),
  payment VARCHAR(120),
  channel VARCHAR(120),
  staff VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS order_items (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  order_id VARCHAR(64) NOT NULL,
  product_id VARCHAR(64),
  product_name VARCHAR(255),
  qty INT DEFAULT 1,
  price BIGINT DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS inventory_logs (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  log_date DATETIME,
  type VARCHAR(64),
  product_id VARCHAR(64),
  product_name VARCHAR(255),
  sku VARCHAR(100),
  qty INT DEFAULT 0,
  warehouse VARCHAR(255),
  note TEXT,
  staff VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS purchase_orders (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  supplier VARCHAR(255),
  order_date DATE,
  expected_date DATE,
  total BIGINT DEFAULT 0,
  paid BIGINT DEFAULT 0,
  status VARCHAR(64),
  items_count INT DEFAULT 0,
  staff VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS returns (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  order_id VARCHAR(64),
  customer VARCHAR(255),
  return_date DATE,
  product VARCHAR(255),
  qty INT DEFAULT 1,
  amount BIGINT DEFAULT 0,
  reason TEXT,
  status VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS promotions (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  name VARCHAR(255),
  code VARCHAR(100),
  type VARCHAR(64),
  value BIGINT DEFAULT 0,
  applies_to VARCHAR(255),
  start_date DATE,
  end_date DATE,
  used_count INT DEFAULT 0,
  usage_limit INT DEFAULT 0,
  status VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cashbook_entries (
  id VARCHAR(64) PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  entry_date DATETIME,
  type VARCHAR(64),
  category VARCHAR(120),
  amount BIGINT DEFAULT 0,
  method VARCHAR(120),
  ref VARCHAR(120),
  staff VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS app_settings (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  setting_key VARCHAR(120) NOT NULL,
  setting_value TEXT,
  UNIQUE KEY uq_store_setting (store_id, setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  store_id VARCHAR(64) NOT NULL,
  actor VARCHAR(255),
  action VARCHAR(120),
  target_type VARCHAR(120),
  target_id VARCHAR(120),
  detail TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


